const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);function ema(p){let a=Array(M.length),k=2/(p+1),x=M[0].c;for(let i=0;i<M.length;i++){x=i?M[i].c*k+x*(1-k):x;a[i]=x}return a}function atr(p=14){let a=Array(M.length).fill(NaN);for(let i=p;i<M.length;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));a[i]=s/p}return a}const E9=ema(9),E21=ema(21),E50=ema(50),A=atr();function run(q){let sig=new Set;for(let i=60;i<M.length-1;i++){let b=M[i],a=A[i],hr=new Date(b.t).getUTCHours();if(hr===20||q.block.includes(hr)||![a,E9[i],E21[i],E50[i],E21[i-3]].every(Number.isFinite)||!(a>0))continue;let rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<q.body||Math.abs(E9[i]-E21[i])/a<q.sep)continue;if(!(E9[i]>E21[i]&&E21[i]>E50[i]&&E21[i]>E21[i-3]))continue;let is=i-4,ie=i-2,imp=M[ie].c-M[is].o;if(imp<q.imp*a)continue;let pl=Infinity;for(let j=ie+1;j<i;j++)pl=Math.min(pl,M[j].l);let re=(M[ie].c-pl)/imp;if(re<.12||re>.45)continue;if((b.c-b.l)/rg<q.pos||b.c<=M[i-1].h)continue;sig.add(i)}let out=[],p=null;for(let i=60;i<M.length;i++){if(p){let b=M[i],sl=b.l<=p.sl,tp=b.h>=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c;out.push({t:M[p.si].t,r:(px-p.en)/p.risk,h:new Date(M[p.si].t).getUTCHours()});p=null}if(p)continue}let si=i-1;if(sig.has(si)){let en=M[i].o,risk=2*A[si];p={en,risk,sl:en-risk,tp:en+risk,ei:i,si}}}return out}function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else{if(x.r<0)gl+=-x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;const C=[['BASE',{block:[],sep:.08,imp:1.3,body:.55,pos:.66}],['A #2324',{block:[7,13,16,17],sep:.10,imp:1.4,body:.55,pos:.78}],['B #2452',{block:[7,13,16,17],sep:.15,imp:1.4,body:.55,pos:.78}],['C #1176',{block:[16,17],sep:.15,imp:1.4,body:.60,pos:.78}],['D #1164',{block:[16,17],sep:.15,imp:1.3,body:.65,pos:.78}],['E #2508',{block:[7,13,16,17],sep:.18,imp:1.3,body:.65,pos:.78}]],R=C.map(([n,q])=>[n,run(q)]);console.log('MICRO PULLBACK — FINAL WALK-FORWARD\nFULL PERIOD');R.forEach(([n,t])=>console.log(n.padEnd(9),F(S(t))));let lo=M[0].t,hi=M.at(-1).t,sp=(hi-lo)/6,W={};R.forEach(([n])=>W[n]={pos:0,pf:0,better:0});console.log('\n6-BLOCK STABILITY');for(let k=0;k<6;k++){let a=lo+k*sp,b=k===5?hi+1:lo+(k+1)*sp,bs=S(R[0][1].filter(x=>x.t>=a&&x.t<b));console.log(`\nBLOCK ${k+1} ${new Date(a).toISOString().slice(0,10)} → ${new Date(b-1).toISOString().slice(0,10)}`);for(const[n,t]of R){let s=S(t.filter(x=>x.t>=a&&x.t<b));console.log(n.padEnd(9),F(s));if(s.net>0)W[n].pos++;if(s.pf>=1)W[n].pf++;if(n!=='BASE'&&s.pf>=bs.pf&&s.dd<=bs.dd)W[n].better++}}console.log('\nSCORECARD');for(const[n]of R){let w=W[n];console.log(`${n.padEnd(9)} positive ${w.pos}/6 | PF>=1 ${w.pf}/6${n==='BASE'?'':` | PF>=BASE & DD<=BASE ${w.better}/6`}`)}console.log('\nRECENT JUL→END');let recent=Date.UTC(2026,6,1);R.forEach(([n,t])=>console.log(n.padEnd(9),F(S(t.filter(x=>x.t>=recent)))));console.log('\nMONTHLY LAST 6');for(let mo=3;mo<=8;mo++){let a=Date.UTC(2026,mo,1),b=mo===11?Date.UTC(2027,0,1):Date.UTC(2026,mo+1,1);console.log(`2026-${String(mo+1).padStart(2,'0')}`);R.forEach(([n,t])=>console.log(' ',n.padEnd(9),F(S(t.filter(x=>x.t>=a&&x.t<b)))))}console.log('\nChoose stability, not optimizer rank.');